  } ]
}, {
  "tStartMs": 1563912,
  "dDurationMs": 1501,
  "segs": [ {
    "utf8": "從我們童年就開始"
  } ]
}, {
  "tStartMs": 1565413,
  "dDurationMs": 1702,
  "segs": [ {
    "utf8": "好 現在就講到一個"
  } ]
}, {
  "tStartMs": 1567115,
  "dDurationMs": 1535,
  "segs": [ {

text:
    "utf8": "其實我們剛剛講到有場地 "
  } ]
}, {
  "tStartMs": 1568650,
  "dDurationMs": 1068,
  "segs": [ {
    "utf8": "有基礎設施"
  } ]
}, {
  "tStartMs": 1569718,
  "dDurationMs": 901,
  "segs": [ {
    "utf8": "再來就是"
  } ]
}, {
  "tStartMs": 1570619,
  "dDurationMs": 1901,
  "segs": [ {
    "utf8": "仲間（Nakama）就是同伴"
  } ]
}, {
  "tStartMs": 1572520,
  "dDurationMs": 2086,
  "segs": [ {
    "utf8": "我們兩個可以不同的世代"
  } ]
}, {
  "tStartMs": 1574606,
  "dDurationMs": 1401,
  "segs": [ {
    "utf8": "其實差距一個世代"
  } ]
}, {
  "tStartMs": 1576007,
  "dDurationMs": 1702,
  "segs": [ {
    "utf8": "我們還是可以聊這些作品"
  } ]
}, {
  "tStartMs": 1577709,
  "dDurationMs": 1468,
  "segs": [ {
    "utf8": "聊得非常的開心"
  } ]
}, {
  "tStartMs": 1579177,
  "dDurationMs": 2035,
  "segs": [ {
    "utf8": "但是對於這個怎麼講"
  } ]
}, {
  "tStartMs": 1581212,
  "dDurationMs": 1702,
  "segs": [ {
    "utf8": "對於我剛剛講到的"
  } ]
}, {
  "tStartMs": 1582914,
  "dDurationMs": 1068,
  "segs": [ {
    "utf8": "五年級世代 "
  } ]
}, {
  "tStartMs": 1583982,
  "dDurationMs": 1535,
  "segs": [ {
    "utf8": "我知道了很多的朋友"
  } ]
}, {
  "tStartMs": 1585517,
  "dDurationMs": 1868,
  "segs": [ {
    "utf8": "他們可能過去會去參加一些 "
  } ]
}, {
  "tStartMs": 1587385,
  "dDurationMs": 1318,
  "segs": [ {
    "utf8": "民歌演唱會"
  } ]
}, {
  "tStartMs": 1588703,
  "dDurationMs": 1118,
  "segs": [ {
    "utf8": "然後或者伍佰"
  } ]
}, {
  "tStartMs": 1589821,
  "dDurationMs": 1785,
  "segs": [ {
    "utf8": "那時候伍佰紅的時候"
  } ]
}, {
  "tStartMs": 1591606,
  "dDurationMs": 2002,
  "segs": [ {
    "utf8": "也是大概九零年代初期"
  } ]
}, {
  "tStartMs": 1593608,
  "dDurationMs": 2102,
  "segs": [ {
    "utf8": "有一些Live的這個場地"
  } ]
}, {
  "tStartMs": 1595710,
  "dDurationMs": 1201,
  "segs": [ {
    "utf8": "那現在怎麼講 "
  } ]
}, {
  "tStartMs": 1596911,
  "dDurationMs": 2403,
  "segs": [ {
    "utf8": "可以去滿足他們的場地"
  } ]
}, {
  "tStartMs": 1599314,
  "dDurationMs": 1151,
  "segs": [ {
    "utf8": "我也不知道在哪裡"
  } ]
}, {
  "tStartMs": 1600465,
  "dDurationMs": 1652,
  "segs": [ {
    "utf8": " 就是說這邊有一句話"
  } ]
}, {
  "tStartMs": 1602117,
  "dDurationMs": 2002,
  "segs": [ {
    "utf8": "是我們那時候在擬訪綱的時候"
  } ]
}, {
  "tStartMs": 1604119,
  "dDurationMs": 1401,
  "segs": [ {
    "utf8": "我們製作人提出來"
  } ]
}, {
  "tStartMs": 1605520,
  "dDurationMs": 2286,
  "segs": [ {
    "utf8": "他說 你有提到說爬山這件事"
  } ]
}, {
  "tStartMs": 1607806,
  "dDurationMs": 2302,
  "segs": [ {
    "utf8": "台北可以成為一個登山的地方"
  } ]
}, {
  "tStartMs": 1610108,
  "dDurationMs": 2202,
  "segs": [ {
    "utf8": "然後台北是全世界少數"
  } ]
}, {
  "tStartMs": 1612310,
  "dDurationMs": 2002,
  "segs": [ {
    "utf8": "出捷運就能上山的首都"
  } ]
}, {
  "tStartMs": 1614312,
  "dDurationMs": 3003,
  "segs": [ {
    "utf8": "然後你也提到說有四大文化徑"
  } ]
}, {
  "tStartMs": 1617315,
  "dDurationMs": 1452,
  "segs": [ {
    "utf8": "三大登山中心 "
  } ]
}, {
  "tStartMs": 1618767,
  "dDurationMs": 1751,
  "segs": [ {
    "utf8": "場地我們不缺"
  } ]
}, {
  "tStartMs": 1620518,
  "dDurationMs": 1852,
  "segs": [ {
    "utf8": "可是缺同伴這件事情 "
  } ]
}, {
  "tStartMs": 1622370,
  "dDurationMs": 2636,
  "segs": [ {
    "utf8": "比缺場地難太多了"
  } ]
}, {
  "tStartMs": 1625006,
  "dDurationMs": 1702,
  "segs": [ {
    "utf8": "我覺得當然我們有一些人"
  } ]
}, {
  "tStartMs": 1626708,
  "dDurationMs": 3203,
  "segs": [ {
    "utf8": "他是很能夠自己找到一些夥伴"
  } ]
}, {
  "tStartMs": 1629911,
  "dDurationMs": 1702,
  "segs": [ {
    "utf8": "比如說他一天到晚去公園"
  } ]
}, {
  "tStartMs": 1631613,
  "dDurationMs": 1618,
  "segs": [ {
    "utf8": "在那邊泡茶聊天"
  } ]
}, {
  "tStartMs": 1633231,
  "dDurationMs": 2186,
  "segs": [ {
    "utf8": " 或者一起打太極"
  } ]
}, {
  "tStartMs": 1635417,
  "dDurationMs": 2302,
  "segs": [ {
    "utf8": "又或者說他一天到晚去菜市場"
  } ]
}, {
  "tStartMs": 1637719,
  "dDurationMs": 1301,
  "segs": [ {
    "utf8": "所以有一些人是"
  } ]
}, {
  "tStartMs": 1639020,
  "dDurationMs": 2186,
  "segs": [ {
    "utf8": "他有辦法就是他出得了門"
  } ]
}, {
  "tStartMs": 1641206,
  "dDurationMs": 1251,
  "segs": [ {
    "utf8": "然後他也有辦法建立 "
  } ]
}, {
  "tStartMs": 1642457,
  "dDurationMs": 1351,
  "segs": [ {
    "utf8": "人跟人之間的連結"
  } ]
}, {
  "tStartMs": 1643808,
  "dDurationMs": 1051,
  "segs": [ {
    "utf8": "但是有一些人是 "
  } ]
}, {
  "tStartMs": 1644859,
  "dDurationMs": 1752,
  "segs": [ {
    "utf8": "他真的比較沒有在出門"
  } ]
}, {
  "tStartMs": 1646611,
  "dDurationMs": 1502,
  "segs": [ {
    "utf8": "然後他也覺得孤獨"
  } ]
}, {
  "tStartMs": 1648113,
  "dDurationMs": 2002,
  "segs": [ {
    "utf8": "然後他一時間也不知道去找誰"
  } ]
}, {
  "tStartMs": 1650115,
  "dDurationMs": 2002,
  "segs": [ {
    "utf8": "跟以前的同學也沒有什麼聯絡 "
  } ]
}, {
  "tStartMs": 1652117,
  "dDurationMs": 901,
  "segs": [ {
    "utf8": "這是有的"
  } ]
}, {
  "tStartMs": 1653018,
  "dDurationMs": 1084,
  "segs": [ {
    "utf8": "而且越來越多 "
  } ]
}, {
  "tStartMs": 1654102,
  "dDurationMs": 1018,
  "segs": [ {
    "utf8": "沒話講"
  } ]
}, {
  "tStartMs": 1655120,
  "dDurationMs": 600,
  "segs": [ {
    "utf8": "真的是"
  } ]
}, {
  "tStartMs": 1655720,
  "dDurationMs": 1101,
  "segs": [ {
    "utf8": "而且說真的"
  } ]
}, {
  "tStartMs": 1656821,
  "dDurationMs": 1886,
  "segs": [ {
    "utf8": "我雖然不太想講這個題目"
  } ]
}, {
  "tStartMs": 1658707,
  "dDurationMs": 1201,
  "segs": [ {
    "utf8": "但是我的意思是說"
  } ]
}, {
  "tStartMs": 1659908,
  "dDurationMs": 984,
  "segs": [ {
    "utf8": "因為同學之間 "
  } ]
